// Normalize the MultiSet VPS response into a stable pose object.
// If MultiSet is unreachable / not configured / pose not found, fall back to a
// mock pose so the PoC pipeline keeps running end-to-end.
const trigger = $('New Snapshot (Drive Trigger)').first().json;
const vps = $input.first().json || {};

// Mock pose matches Door_101 created by create_sample_ifc.py -> the demo
// works out of the box even without a MultiSet map.
const MOCK_POSE = { x: 2.5, y: 1.0, z: 1.2 };

let pose, confidence, source;
if (vps.poseFound === true && vps.position) {
  pose = { x: vps.position.x, y: vps.position.y, z: vps.position.z };
  confidence = vps.confidence ?? null;
  source = 'multiset';
} else {
  pose = MOCK_POSE;
  confidence = null;
  source = 'mock_fallback';
}

return [{
  json: {
    file_id: trigger.id,
    file_name: trigger.name,
    photo_url: trigger.webViewLink || '',
    pos_x: pose.x,
    pos_y: pose.y,
    pos_z: pose.z,
    localization_source: source,
    localization_confidence: confidence,
    multiset_map_codes: vps.mapCodes || [],
  },
  binary: $('Download Snapshot').first().binary,
}];

// Parse Claude's JSON triage, merge with pose data, map object type to an
// IFC class hint and pre-compute SQL-safe strings.
const raw = ($input.first().json.text || '').trim();
const cleaned = raw.replace(/^```(json)?/i, '').replace(/```$/, '').trim();

let triage;
try {
  triage = JSON.parse(cleaned);
} catch (e) {
  // Never break the pipeline on a malformed LLM answer: degrade to a
  // manual-review ticket instead.
  triage = {
    object_type: 'unknown',
    damage_description: 'Vision triage failed - manual review needed. Raw output: ' + raw.slice(0, 200),
    severity: 'medium',
    required_trade: 'generalist',
    safety_risk: false,
  };
}

const IFC_CLASS = {
  door: 'IfcDoor', window: 'IfcWindow', light: 'IfcLightFixture',
  hvac: 'IfcAirTerminal', plumbing: 'IfcSanitaryTerminal',
  furniture: 'IfcFurniture', wall: 'IfcWall',
};

const sql = (s) => String(s ?? '').replace(/'/g, "''");
const pose = $('Normalize Pose').first().json;
const severity = ['low', 'medium', 'high', 'critical'].includes(triage.severity)
  ? triage.severity : 'medium';

return [{
  json: {
    ...pose,
    object_type: triage.object_type || 'unknown',
    damage_description: triage.damage_description || '',
    severity,
    required_trade: triage.required_trade || 'generalist',
    safety_risk: triage.safety_risk === true,
    ifc_class_hint: IFC_CLASS[(triage.object_type || '').toLowerCase()] || null,
    object_type_sql: sql(triage.object_type || 'unknown'),
    damage_description_sql: sql(triage.damage_description || ''),
    required_trade_sql: sql(triage.required_trade || 'generalist'),
  },
}];

