// Collect the RAG hits into one JSON blob and compute a deterministic time
// slot from severity. Scheduling is a business rule (SLA policy), so it is
// deliberately NOT delegated to the LLM: date arithmetic must be exact.
const hits = $input.all().map(i => i.json).filter(j => j && Object.keys(j).length > 0);
const ticket = $('Create Ticket').first().json;
const triage = $('Parse Triage and Map IFC Class').first().json;

function nextBusinessDayAt(base, addDays, hour) {
  const d = new Date(base);
  let added = 0;
  while (added < addDays) {
    d.setDate(d.getDate() + 1);
    const w = d.getDay();
    if (w !== 0 && w !== 6) added++;
  }
  d.setHours(hour, 0, 0, 0);
  return d;
}

const now = new Date();
let slot;
switch (triage.severity) {
  case 'critical': slot = new Date(now.getTime() + 4 * 3600 * 1000); slot.setMinutes(0, 0, 0); break; // SLA: +4h
  case 'high':     slot = nextBusinessDayAt(now, 1, 9); break;  // next business day 09:00
  case 'medium':   slot = nextBusinessDayAt(now, 3, 9); break;  // +3 business days
  default:         slot = nextBusinessDayAt(now, 7, 9); break;  // low: +7 business days
}

return [{
  json: {
    ticket_id: ticket.id,
    candidates_json: JSON.stringify(hits),
    slot_iso: slot.toISOString(),
    slot_human: slot.toLocaleString('en-GB', { timeZone: 'Europe/Rome', dateStyle: 'full', timeStyle: 'short' }),
    object_type: triage.object_type,
    damage_description: triage.damage_description,
    severity: triage.severity,
    required_trade: triage.required_trade,
    ifc_global_id: ticket.ifc_global_id,
    photo_url: ticket.photo_url,
  },
}];

