// Turn Claude's ranked list into one n8n item per technician (the dispatch
// queue consumed by the sequential loop). Empty list -> escalation flag.
const raw = ($input.first().json.text || '').trim()
  .replace(/^```(json)?/i, '').replace(/```$/, '').trim();

let queue = [];
try {
  const parsed = JSON.parse(raw);
  if (Array.isArray(parsed)) queue = parsed;
} catch (e) { /* fall through to escalation */ }

const base = $('Aggregate Candidates and Propose Slot').first().json;
const sql = (s) => String(s ?? '').replace(/'/g, "''");
queue = queue.filter(t => t && t.email);

if (queue.length === 0) {
  return [{ json: { no_candidates: true, ticket_id: base.ticket_id } }];
}

return queue.map((t, i) => ({
  json: {
    rank: i + 1,
    tech_id: String(t.tech_id ?? ''),
    name: t.name || 'Technician',
    name_sql: sql(t.name || 'Technician'),
    email: t.email,
    reason: t.reason || '',
    ...base,
  },
}));
